package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import jakarta.servlet.http.Cookie;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ScheduleApiTest {
 ScheduleStore store;SpaceAuthorizationClient auth;ScheduleController api;UUID space,schedule,actor;String body="{\"title\":\"Schedule\",\"description\":\"Body\",\"startsAt\":\"2028-03-12T06:30:00Z\",\"endsAt\":\"2028-03-12T07:30:00Z\",\"timeZone\":\"America/New_York\",\"taskId\":null}";
 @BeforeEach void init(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();schedule=ids.next();actor=ids.next();store=mock(ScheduleStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyString(),eq("PRIVATE"),anyString())).thenReturn(actor);api=new ScheduleController(store,auth,new SimpleMeterRegistry(),"https://localhost:8443");}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/schedules/"+schedule);r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 ScheduleStore.Schedule value(){return new ScheduleStore.Schedule(schedule,space,"PRIVATE","ACTIVE",1,"Schedule","Body","2028-03-12T06:30:00Z","2028-03-12T07:30:00Z","America/New_York","2028-03-12T01:30:00","2028-03-12T03:30:00","-05:00","-04:00",null,Instant.now().toString(),Instant.now().toString());}
 @Test void everyReadChecksLivePrivateAuthorityAndNeverCaches(){when(store.get(space,schedule)).thenReturn(value());for(int i=0;i<2;i++){var response=api.get(space.toString(),schedule.toString(),r("GET",null));assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals("\"sc1\"",response.getHeaders().getETag());}verify(auth,times(2)).authorize(eq(space),eq("a".repeat(43)),eq("SCHEDULE_READ"),eq("PRIVATE"),anyString());reset(store);when(auth.authorize(eq(space),any(),anyString(),eq("PRIVATE"),anyString())).thenThrow(new ResponseStatusException(HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),schedule.toString(),r("GET",null)));verifyNoInteractions(store);}
 @Test void createRequiresSingleOpaqueKeyAndReturnsOriginalReplayRepresentation()throws Exception{var missing=r("POST",body);assertThrows(ResponseStatusException.class,()->api.create(space.toString(),missing));var duplicate=r("POST",body);duplicate.addHeader("Idempotency-Key","a".repeat(32));duplicate.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->api.create(space.toString(),duplicate));when(store.create(eq(space),eq(actor),eq("c".repeat(32)),any(),anyString())).thenReturn(new ScheduleStore.Creation(value(),true));var valid=r("POST",body);valid.addHeader("Idempotency-Key","c".repeat(32));assertEquals(200,api.create(space.toString(),valid).getStatusCode().value());}
 @Test void editsRequireStrongIndependentVersionAndStrictSixFieldJson()throws Exception{assertEquals(428,assertThrows(ResponseStatusException.class,()->api.update(space.toString(),schedule.toString(),r("PUT",body))).getStatusCode().value());for(String tag:List.of("\"rm1\"","\"sc0\"","\"sc01\"","W/\"sc1\"","*","\"sc9223372036854775808\"")){var req=r("PUT",body);req.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.update(space.toString(),schedule.toString(),req));}for(String bad:List.of("{}",body+" {}",body.replace("\"title\":\"Schedule\"","\"title\":\"One\",\"title\":\"Two\""),body.replace("null","123"),body.substring(0,body.length()-1)+",\"actorId\":\"spoof\"}")){var req=r("PUT",bad);req.addHeader("If-Match","\"sc1\"");assertThrows(ResponseStatusException.class,()->api.update(space.toString(),schedule.toString(),req));}verifyNoInteractions(store);}
 @Test void originCredentialsGetBodiesAndDuplicateQueriesAreRejected(){var cross=r("DELETE",null);cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.retire(space.toString(),schedule.toString(),cross)).getStatusCode().value());var body=r("GET","{}");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),body));var dup=r("GET",null);dup.addParameter("status","ALL","COMPLETED");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),dup));var bad=r("GET",null);bad.addParameter("unknown","PUBLIC");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),bad));verifyNoInteractions(store,auth);}
 @Test void resolverIsReadOnlyFreshAuthorizedAndUncacheable(){var req=r("GET",null);req.addParameter("local","2028-11-05T01:30:00");req.addParameter("timeZone","America/New_York");for(int n=0;n<2;n++){var result=api.options(space.toString(),req);assertEquals(2,result.getBody().options().size());assertEquals("no-store",result.getHeaders().getCacheControl());}verify(auth,times(2)).authorize(eq(space),any(),eq("SCHEDULE_READ"),eq("PRIVATE"),anyString());verifyNoInteractions(store);}
 @Test void httpErrorsKeepStatusAndPrivacyHeaders()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(api).setControllerAdvice(new GoalErrors()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/spaces/"+space+"/schedules/"+schedule).secure(true).cookie(new Cookie("__Host-brain_guest","a".repeat(43))).header("Origin","https://localhost:8443").contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(428)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Cache-Control","no-store"));}
}
